-- ai_agent
CREATE TABLE IF NOT EXISTS "ai_agent" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 0,
  "agent_name" varchar(100) NOT NULL,
  "agent_code" varchar(50) NOT NULL,
  "description" varchar(500) DEFAULT NULL,
  "system_prompt" text NOT NULL,
  "provider_id" bigint DEFAULT NULL,
  "model_name" varchar(100) DEFAULT NULL,
  "model_selection_mode" varchar(16) NOT NULL DEFAULT 'PINNED',
  "route_policy_id" bigint DEFAULT NULL,
  "temperature" numeric(3,2) DEFAULT 0.70,
  "max_tokens" integer DEFAULT 4000,
  "extra_config" text DEFAULT NULL,
  "greeting" varchar(500) DEFAULT NULL,
  "preset_questions" text,
  "max_iters" integer DEFAULT 10,
  "knowledge_ids" text,
  "rag_mode" varchar(32) DEFAULT 'none',
  "tool_group_mode" varchar(32) DEFAULT 'all',
  "asr_model_id" bigint DEFAULT NULL,
  "tts_model_id" bigint DEFAULT NULL,
  "status" char(1) NOT NULL DEFAULT '0',
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp DEFAULT NULL,
  "del_flag" bigint NOT NULL DEFAULT 0,
  "create_dept" varchar(30) DEFAULT NULL,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_agent" IS 'AI Agent配置表';
COMMENT ON COLUMN "ai_agent"."id" IS '主键ID';
