CREATE TABLE IF NOT EXISTS "sys_client" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "client_code" varchar(50) NOT NULL,
  "client_name" varchar(100) NOT NULL,
  "app_id" varchar(64) NOT NULL,
  "app_secret" varchar(128) DEFAULT NULL,
  "client_auth_method" varchar(32) NOT NULL DEFAULT 'client_secret',
  "token_timeout" bigint DEFAULT 7200,
  "token_activity_timeout" bigint DEFAULT -1,
  "token_prefix" varchar(20) DEFAULT 'Bearer',
  "token_name" varchar(50) DEFAULT 'Authorization',
  "concurrent_login" smallint DEFAULT 0,
  "share_token" smallint DEFAULT 0,
  "enable_ip_limit" smallint DEFAULT 0,
  "ip_whitelist" text,
  "enable_encrypt" smallint DEFAULT 0,
  "encrypt_algorithm" varchar(50) DEFAULT 'AES',
  "max_user_count" bigint DEFAULT -1,
  "max_online_count" bigint DEFAULT -1,
  "auth_types" varchar(255) DEFAULT 'password',
  "captcha_type" varchar(32) DEFAULT NULL,
  "status" smallint DEFAULT 1,
  "description" varchar(500) DEFAULT NULL,
  "home_url" varchar(512) DEFAULT NULL,
  "tenant_id" bigint DEFAULT NULL,
  "create_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "create_by" bigint DEFAULT NULL,
  "update_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "update_by" bigint DEFAULT NULL,
  "create_dept" bigint DEFAULT NULL,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_client" IS '客户端管理表';
COMMENT ON COLUMN "sys_client"."id" IS '主键ID';
COMMENT ON COLUMN "sys_client"."client_code" IS '客户端编码';
COMMENT ON COLUMN "sys_client"."client_name" IS '客户端名称';
COMMENT ON COLUMN "sys_client"."app_id" IS '应用ID';
COMMENT ON COLUMN "sys_client"."app_secret" IS '应用密钥摘要，仅client_secret客户端使用';
COMMENT ON COLUMN "sys_client"."client_auth_method" IS '客户端认证方式：none/client_secret';
COMMENT ON COLUMN "sys_client"."token_timeout" IS 'Token有效期（秒）';
COMMENT ON COLUMN "sys_client"."token_activity_timeout" IS 'Token活跃超时（秒）';
COMMENT ON COLUMN "sys_client"."token_prefix" IS 'Token前缀';
COMMENT ON COLUMN "sys_client"."token_name" IS 'Token名称';
COMMENT ON COLUMN "sys_client"."concurrent_login" IS '是否允许并发登录（0-否 1-是）';
COMMENT ON COLUMN "sys_client"."share_token" IS '是否共享Token（0-否 1-是）';
COMMENT ON COLUMN "sys_client"."enable_ip_limit" IS '是否启用IP限制';
COMMENT ON COLUMN "sys_client"."ip_whitelist" IS 'IP白名单（JSON数组）';
COMMENT ON COLUMN "sys_client"."enable_encrypt" IS '是否启用加密传输';
COMMENT ON COLUMN "sys_client"."encrypt_algorithm" IS '加密算法';
COMMENT ON COLUMN "sys_client"."max_user_count" IS '最大用户数（-1不限）';
COMMENT ON COLUMN "sys_client"."max_online_count" IS '最大在线数（-1不限）';
COMMENT ON COLUMN "sys_client"."auth_types" IS '支持的认证方式（逗号分隔）';
COMMENT ON COLUMN "sys_client"."captcha_type" IS '验证码类型：graphical图形，slider滑块，sms短信；为空继承全局配置';
COMMENT ON COLUMN "sys_client"."status" IS '状态（0-禁用 1-启用）';
COMMENT ON COLUMN "sys_client"."description" IS '客户端描述';
COMMENT ON COLUMN "sys_client"."home_url" IS '前端入口地址（SSO 跳转 baseUrl，如 http://host/forge-report）';
COMMENT ON COLUMN "sys_client"."tenant_id" IS '租户ID';
CREATE UNIQUE INDEX "sys_client_uk_client_code" ON "sys_client" ("client_code");
CREATE UNIQUE INDEX "sys_client_uk_app_id" ON "sys_client" ("app_id");
CREATE INDEX "sys_client_idx_tenant_id" ON "sys_client" ("tenant_id");

