--
--
-- sys_resource
CREATE TABLE IF NOT EXISTS "sys_resource" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 0,
  "resource_name" varchar(100) NOT NULL,
  "parent_id" bigint NOT NULL DEFAULT 0,
  "resource_type" smallint NOT NULL,
  "sort" integer DEFAULT 0,
  "path" varchar(255) DEFAULT NULL,
  "component" varchar(255) DEFAULT NULL,
  "is_external" smallint DEFAULT 0,
  "sso_enabled" smallint DEFAULT 0,
  "sso_target_client" varchar(64) DEFAULT NULL,
  "open_target" varchar(20) DEFAULT '_self',
  "is_public" smallint DEFAULT 0,
  "menu_status" smallint DEFAULT 1,
  "visible" smallint DEFAULT 1,
  "perms" varchar(100) DEFAULT NULL,
  "feature_code" varchar(64) DEFAULT NULL,
  "icon" varchar(100) DEFAULT NULL,
  "api_method" varchar(10) DEFAULT NULL,
  "api_url" varchar(255) DEFAULT NULL,
  "keep_alive" smallint DEFAULT 0,
  "always_show" smallint DEFAULT 0,
  "redirect" varchar(255) DEFAULT NULL,
  "remark" varchar(500) DEFAULT NULL,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "client_code" varchar(50) DEFAULT 'pc',
  "min_user_type" integer NOT NULL DEFAULT 2,
  "del_flag" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_resource" IS '系统资源表（菜单/按钮/API）';
COMMENT ON COLUMN "sys_resource"."id" IS '资源ID';
COMMENT ON COLUMN "sys_resource"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "sys_resource"."resource_name" IS '资源名称';
COMMENT ON COLUMN "sys_resource"."parent_id" IS '父级资源ID（0为顶级）';
COMMENT ON COLUMN "sys_resource"."resource_type" IS '资源类型（1-目录，2-菜单，3-按钮，4-API接口）';
COMMENT ON COLUMN "sys_resource"."sort" IS '排序（值越小越靠前）';
COMMENT ON COLUMN "sys_resource"."path" IS '资源路由（菜单/目录用）';
COMMENT ON COLUMN "sys_resource"."component" IS '前端组件路径（菜单用）';
COMMENT ON COLUMN "sys_resource"."is_external" IS '是否外链（0-否，1-是）';
COMMENT ON COLUMN "sys_resource"."sso_enabled" IS '是否启用SSO（0-否，1-是）';
COMMENT ON COLUMN "sys_resource"."sso_target_client" IS 'SSO目标客户端编码';
COMMENT ON COLUMN "sys_resource"."open_target" IS '打开方式：_self-当前页/_blank-新窗口';
COMMENT ON COLUMN "sys_resource"."is_public" IS '是否公开资源（0-否，1-是，公开资源无需权限验证）';
COMMENT ON COLUMN "sys_resource"."menu_status" IS '菜单状态（0-隐藏，1-显示，仅菜单/目录用）';
COMMENT ON COLUMN "sys_resource"."visible" IS '显示状态（0-隐藏，1-显示，所有资源通用）';
COMMENT ON COLUMN "sys_resource"."perms" IS '权限标识（如：sys:user:list，按钮/API用）';
COMMENT ON COLUMN "sys_resource"."feature_code" IS '功能授权编码，空表示不受授权控制';
COMMENT ON COLUMN "sys_resource"."icon" IS '图标（菜单/目录用）';
COMMENT ON COLUMN "sys_resource"."api_method" IS 'API请求方法（GET/POST/PUT/DELETE，仅API用）';
COMMENT ON COLUMN "sys_resource"."api_url" IS 'API接口地址（仅API用）';
COMMENT ON COLUMN "sys_resource"."keep_alive" IS '是否缓存（0-否，1-是，菜单用）';
COMMENT ON COLUMN "sys_resource"."always_show" IS '是否总是显示（0-否，1-是，菜单用）';
COMMENT ON COLUMN "sys_resource"."redirect" IS '重定向地址（菜单用）';
COMMENT ON COLUMN "sys_resource"."remark" IS '备注';
COMMENT ON COLUMN "sys_resource"."create_by" IS '创建者';
COMMENT ON COLUMN "sys_resource"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_resource"."update_by" IS '更新者';
COMMENT ON COLUMN "sys_resource"."update_time" IS '更新时间';
COMMENT ON COLUMN "sys_resource"."create_dept" IS '创建组织ID';
COMMENT ON COLUMN "sys_resource"."client_code" IS '客户端代码：pc/app';
COMMENT ON COLUMN "sys_resource"."min_user_type" IS '最低可访问用户类型（0-系统管理员，1-租户管理员，2-普通用户）';
COMMENT ON COLUMN "sys_resource"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
CREATE UNIQUE INDEX "sys_resource_uk_tenant_resource_active" ON "sys_resource" ("tenant_id", "resource_type", "perms", "client_code", "del_flag");
CREATE INDEX "sys_resource_idx_tenant_parent" ON "sys_resource" ("tenant_id", "parent_id");
CREATE INDEX "sys_resource_idx_resource_type" ON "sys_resource" ("resource_type");
CREATE INDEX "sys_resource_idx_resource_menu_tree" ON "sys_resource" ("client_code", "del_flag", "sort", "create_time" DESC);

