--
-- sys_sms_config
CREATE TABLE IF NOT EXISTS "sys_sms_config" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "config_id" varchar(64) DEFAULT NULL,
  "supplier" varchar(32) NOT NULL,
  "access_key_id" varchar(128) DEFAULT NULL,
  "access_key_secret" varchar(256) DEFAULT NULL,
  "signature" varchar(64) DEFAULT NULL,
  "template_id" varchar(64) DEFAULT NULL,
  "scene_templates" text,
  "weight" integer DEFAULT 1,
  "retry_interval" integer DEFAULT 5,
  "max_retries" integer DEFAULT 0,
  "maximum" integer DEFAULT NULL,
  "extra_config" text,
  "daily_limit" integer DEFAULT NULL,
  "minute_limit" integer DEFAULT NULL,
  "status" smallint DEFAULT 0,
  "channel_role" varchar(16) NOT NULL DEFAULT 'SECONDARY',
  "tenant_id" bigint DEFAULT NULL,
  "create_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "create_by" varchar(64) DEFAULT NULL,
  "update_by" varchar(64) DEFAULT NULL,
  "remark" varchar(500) DEFAULT NULL,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_sms_config" IS '短信配置表';
COMMENT ON COLUMN "sys_sms_config"."id" IS '主键';
COMMENT ON COLUMN "sys_sms_config"."config_id" IS '配置标识';
COMMENT ON COLUMN "sys_sms_config"."supplier" IS '厂商标识(alibaba/tencent/huawei等)';
COMMENT ON COLUMN "sys_sms_config"."access_key_id" IS '访问密钥ID';
COMMENT ON COLUMN "sys_sms_config"."access_key_secret" IS '访问密钥Secret';
COMMENT ON COLUMN "sys_sms_config"."signature" IS '短信签名';
COMMENT ON COLUMN "sys_sms_config"."template_id" IS '默认模板ID';
COMMENT ON COLUMN "sys_sms_config"."scene_templates" IS '场景模板映射 JSON';
COMMENT ON COLUMN "sys_sms_config"."weight" IS '权重(负载均衡)';
COMMENT ON COLUMN "sys_sms_config"."retry_interval" IS '重试间隔(秒)';
COMMENT ON COLUMN "sys_sms_config"."max_retries" IS '最大重试次数';
COMMENT ON COLUMN "sys_sms_config"."maximum" IS '发送上限';
COMMENT ON COLUMN "sys_sms_config"."extra_config" IS '额外配置(JSON格式)';
COMMENT ON COLUMN "sys_sms_config"."daily_limit" IS '每日发送上限';
COMMENT ON COLUMN "sys_sms_config"."minute_limit" IS '每分钟发送上限';
COMMENT ON COLUMN "sys_sms_config"."status" IS '状态(0禁用 1启用)';
COMMENT ON COLUMN "sys_sms_config"."channel_role" IS 'PRIMARY/SECONDARY';
COMMENT ON COLUMN "sys_sms_config"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "sys_sms_config"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_sms_config"."update_time" IS '更新时间';
COMMENT ON COLUMN "sys_sms_config"."create_by" IS '创建人';
COMMENT ON COLUMN "sys_sms_config"."update_by" IS '更新人';
COMMENT ON COLUMN "sys_sms_config"."remark" IS '备注';
CREATE INDEX "sys_sms_config_idx_tenant_status" ON "sys_sms_config" ("tenant_id", "status");

