COMMENT ON TABLE "sys_social_config" IS '企业协同连接表（原三方登录配置表）';
COMMENT ON COLUMN "sys_social_config"."id" IS '主键ID';
COMMENT ON COLUMN "sys_social_config"."platform" IS '平台类型（WECHAT、WECOM、DINGTALK、GITHUB、GITEE等）';
